INSERT INTO feedback_requests (id, user_id, common_resume_id, category, content, created_at) VALUES
(911001, '00000000-0000-4000-8000-000000910101', 914101, 'FRONTEND', '프로젝트 성과를 더 구체적으로 설명하고 싶어요. 사용자 증가 수치를 어떻게 표현하면 좋을까요? 특히 첫 번째 프로젝트를 중심으로 보고 싶습니다.', CURRENT_TIMESTAMP - INTERVAL '5' MONTH),
(911002, '00000000-0000-4000-8000-000000910102', 914102, 'BACKEND', '백엔드 API 개선 경험이 잘 드러나는지 피드백 부탁드립니다. 특히 첫 번째 프로젝트를 중심으로 보고 싶습니다.', CURRENT_TIMESTAMP - INTERVAL '5' MONTH),
(911003, '00000000-0000-4000-8000-000000910103', 914103, 'FULLSTACK', '협업 경험을 이력서에 어떻게 풀어야 할지 고민입니다. 특히 첫 번째 프로젝트를 중심으로 보고 싶습니다.', CURRENT_TIMESTAMP - INTERVAL '5' MONTH),
(911004, '00000000-0000-4000-8000-000000910101', 914101, 'FRONTEND', '포트폴리오 소개 문장이 너무 길지 않은지 봐주세요. 특히 첫 번째 프로젝트를 중심으로 보고 싶습니다.', CURRENT_TIMESTAMP - INTERVAL '5' MONTH),
(911005, '00000000-0000-4000-8000-000000910102', 914102, 'BACKEND', '기술 스택을 나열하는 방식이 적절한지 의견 부탁드립니다. 특히 첫 번째 프로젝트를 중심으로 보고 싶습니다.', CURRENT_TIMESTAMP - INTERVAL '5' MONTH),
(911006, '00000000-0000-4000-8000-000000910101', 914101, 'FRONTEND', '장애 대응 경험을 지원 직무와 연결하고 싶습니다. 특히 첫 번째 프로젝트를 중심으로 보고 싶습니다.', CURRENT_TIMESTAMP - INTERVAL '5' MONTH),
(911007, '00000000-0000-4000-8000-000000910102', 914102, 'BACKEND', '데이터 처리 프로젝트의 핵심 성과가 전달되는지 궁금합니다. 특히 첫 번째 프로젝트를 중심으로 보고 싶습니다.', CURRENT_TIMESTAMP - INTERVAL '5' MONTH),
(911008, '00000000-0000-4000-8000-000000910103', 914103, 'FULLSTACK', '자기소개 문단이 지원 동기를 충분히 보여주는지 확인 부탁드립니다. 특히 첫 번째 프로젝트를 중심으로 보고 싶습니다.', CURRENT_TIMESTAMP - INTERVAL '5' MONTH),
(911009, '00000000-0000-4000-8000-000000910104', 914104, 'FRONTEND', '프로젝트 성과를 더 구체적으로 설명하고 싶어요. 사용자 증가 수치를 어떻게 표현하면 좋을까요? 최근 수정한 문장을 기준으로 봐주세요.', CURRENT_TIMESTAMP - INTERVAL '5' MONTH),
