INSERT INTO feedback_comments (comment_id, feedback_id, user_id, section, content, is_adopted, adopted_at, created_at) VALUES
(912001, 911001, '00000000-0000-4000-8000-000000910001', 'PROJECTS', '증가율과 함께 비교 기간과 측정 지표를 적으면 성과가 더 명확해집니다.', true, CURRENT_TIMESTAMP - INTERVAL '4' MONTH, CURRENT_TIMESTAMP - INTERVAL '5' MONTH),
(912002, 911002, '00000000-0000-4000-8000-000000910001', 'SKILLS', '응답 시간이 얼마나 줄었는지와 측정 방법을 한 문장으로 추가해 보세요.', true, CURRENT_TIMESTAMP - INTERVAL '4' MONTH, CURRENT_TIMESTAMP - INTERVAL '5' MONTH),
(912003, 911003, '00000000-0000-4000-8000-000000910001', 'INTRODUCTION', '맡은 역할과 팀원과의 의사결정 과정을 나누어 쓰면 기여도가 선명해집니다.', true, CURRENT_TIMESTAMP - INTERVAL '4' MONTH, CURRENT_TIMESTAMP - INTERVAL '5' MONTH),
(912004, 911004, '00000000-0000-4000-8000-000000910001', 'PROJECTS', '첫 문장에 해결한 문제를 두고 구현 기술은 다음 문장으로 나누면 읽기 편합니다.', true, CURRENT_TIMESTAMP - INTERVAL '4' MONTH, CURRENT_TIMESTAMP - INTERVAL '5' MONTH),
(912005, 911005, '00000000-0000-4000-8000-000000910001', 'SKILLS', '단순 목록보다 각 기술을 어디에 적용했는지 프로젝트 경험과 연결해 주세요.', true, CURRENT_TIMESTAMP - INTERVAL '4' MONTH, CURRENT_TIMESTAMP - INTERVAL '5' MONTH),
(912006, 911006, '00000000-0000-4000-8000-000000910002', 'INTRODUCTION', '장애 원인, 조치, 재발 방지 순서로 정리하면 문제 해결 과정이 잘 보입니다.', true, CURRENT_TIMESTAMP - INTERVAL '4' MONTH, CURRENT_TIMESTAMP - INTERVAL '5' MONTH),
(912007, 911007, '00000000-0000-4000-8000-000000910002', 'PROJECTS', '처리량과 정확도 같은 수치를 기준 환경과 함께 적어 보세요.', true, CURRENT_TIMESTAMP - INTERVAL '4' MONTH, CURRENT_TIMESTAMP - INTERVAL '5' MONTH),
(912008, 911008, '00000000-0000-4000-8000-000000910002', 'SKILLS', '입사 후 기여할 수 있는 경험을 먼저 제시하면 지원 동기가 더 설득력 있게 읽힙니다.', true, CURRENT_TIMESTAMP - INTERVAL '4' MONTH, CURRENT_TIMESTAMP - INTERVAL '5' MONTH),
(912009, 911009, '00000000-0000-4000-8000-000000910002', 'INTRODUCTION', '증가율과 함께 비교 기간과 측정 지표를 적으면 성과가 더 명확해집니다.', true, CURRENT_TIMESTAMP - INTERVAL '4' MONTH, CURRENT_TIMESTAMP - INTERVAL '5' MONTH),
(912010, 911010, '00000000-0000-4000-8000-000000910002', 'PROJECTS', '응답 시간이 얼마나 줄었는지와 측정 방법을 한 문장으로 추가해 보세요.', true, CURRENT_TIMESTAMP - INTERVAL '4' MONTH, CURRENT_TIMESTAMP - INTERVAL '5' MONTH),
(912011, 911011, '00000000-0000-4000-8000-000000910002', 'SKILLS', '맡은 역할과 팀원과의 의사결정 과정을 나누어 쓰면 기여도가 선명해집니다.', true, CURRENT_TIMESTAMP - INTERVAL '4' MONTH, CURRENT_TIMESTAMP - INTERVAL '5' MONTH),
(912012, 911012, '00000000-0000-4000-8000-000000910002', 'INTRODUCTION', '첫 문장에 해결한 문제를 두고 구현 기술은 다음 문장으로 나누면 읽기 편합니다.', true, CURRENT_TIMESTAMP - INTERVAL '4' MONTH, CURRENT_TIMESTAMP - INTERVAL '5' MONTH),
(912013, 911013, '00000000-0000-4000-8000-000000910002', 'PROJECTS', '단순 목록보다 각 기술을 어디에 적용했는지 프로젝트 경험과 연결해 주세요.', true, CURRENT_TIMESTAMP - INTERVAL '4' MONTH, CURRENT_TIMESTAMP - INTERVAL '5' MONTH),
